class Solution {
    struct TrieNode {
        TrieNode* children[2] = {};
    };
public:
    int findMaximumXOR(vector<int>& nums) {
        TrieNode* root = new TrieNode();
        for (int num : nums) {
            TrieNode* curr = root;
            for (int i = 31; i >= 0; --i) {
                int bit = (num >> i) & 1;
                if (!curr->children[bit]) curr->children[bit] = new TrieNode();
                curr = curr->children[bit];
            }
        }

        int maxXor = 0;
        for (int num : nums) {
            TrieNode* curr = root;
            int curXor = 0;
            for (int i = 31; i >= 0; --i) {
                int bit = (num >> i) & 1;
                int toggled = 1 - bit;
                if (curr->children[toggled]) {
                    curXor |= (1 << i);
                    curr = curr->children[toggled];
                } else {
                    curr = curr->children[bit];
                }
            }
            maxXor = max(maxXor, curXor);
        }
        return maxXor;
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[2];
    }
    public int findMaximumXOR(int[] nums) {
        TrieNode root = new TrieNode();
        for (int num : nums) {
            TrieNode curr = root;
            for (int i = 31; i >= 0; --i) {
                int bit = (num >> i) & 1;
                if (curr.children[bit] == null) curr.children[bit] = new TrieNode();
                curr = curr.children[bit];
            }
        }

        int maxXor = 0;
        for (int num : nums) {
            TrieNode curr = root;
            int curXor = 0;
            for (int i = 31; i >= 0; --i) {
                int bit = (num >> i) & 1;
                int toggled = 1 - bit;
                if (curr.children[toggled] != null) {
                    curXor |= (1 << i);
                    curr = curr.children[toggled];
                } else {
                    curr = curr.children[bit];
                }
            }
            maxXor = Math.max(maxXor, curXor);
        }
        return maxXor;
    }
}

var findMaximumXOR = function(nums) {
    const root = {};
    for (const num of nums) {
        let curr = root;
        for (let i = 31; i >= 0; --i) {
            const bit = (num >>> i) & 1;
            if (!curr[bit]) curr[bit] = {};
            curr = curr[bit];
        }
    }

    let maxXor = 0;
    for (const num of nums) {
        let curr = root;
        let curXor = 0;
        for (let i = 31; i >= 0; --i) {
            const bit = (num >>> i) & 1;
            const toggled = 1 - bit;
            if (curr[toggled]) {
                curXor = (curXor | (1 << i)) >>> 0;
                curr = curr[toggled];
            } else {
                curr = curr[bit];
            }
        }
        if (curXor > maxXor) maxXor = curXor;
    }
    return maxXor;
};
